reg llm_go_signal = 1;

  reg clk;
  reg rst_n;
  reg data_in;
  wire data_out;

  // Instantiate the DUT (Design Under Test)
  pulse_detect dut (
    .clk(clk),
    .rst_n(rst_n),
    .data_in(data_in),
    .data_out(data_out)
  );

  // Generate clock
  initial begin
	clk=0;
	forever #5 clk=~clk;
  end

  integer error = 0;
  initial begin
      // Initialize inputs
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

      #10;
      rst_n = 0;
      data_in = 0;
      #28;
      rst_n = 1;
      #10      data_in = 0;
      #10      data_in = 0;  
      #10      data_in = 0;
      #10      data_in = 1;
      #10      data_in = 0;
      #10      data_in = 1;
      #10      data_in = 0;
      #10      data_in = 1;
      #10      data_in = 1;
      #10      data_in = 0;
      #10;
      // Finish simulation
      $finish;
  end

  initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

    #5;
    #10;
    error = (data_out == 0) ? error : error+1;
    #10;
    error = (data_out == 0) ? error : error+1;
    #10;
    error = (data_out == 0) ? error : error+1;
    #10;
    error = (data_out == 0) ? error : error+1;
    #10;
    error = (data_out == 0) ? error : error+1;
    #10;
    error = (data_out == 0) ? error : error+1;
    #10;
    error = (data_out == 0) ? error : error+1;
    #10;
    error = (data_out == 0) ? error : error+1;
    #10;
    error = (data_out == 1) ? error : error+1;
    // $display("%b,%b,%b", data_in, data_out, dut.pulse_level1);//1
    #20;
    error = (data_out == 1) ? error : error+1;
    #10;
    if (error == 0) begin
        $display("===========Your Design Passed===========");
    end
    else begin
    $display("===========Error===========");
    end
  end




        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "data_out,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", data_out);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests (Synchronization)
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting Deterministic Mutation Stimuli...");

    // Initialize Inputs
    rst_n = 0;
    data_in = 0;

    // Reset Sequence
    #20;
    @(negedge clk);
    rst_n = 1;

    // ------------------------------------------------------------
    // Sequence 1: Basic Pulse Detection (0 -> 1 -> 0)
    // Target: Verify correct state transitions s0->s1->s2->s3
    // ------------------------------------------------------------

    // Step 1: s0 -> s0 (Verify idle stability with Input 1)
    @(negedge clk);
    data_in = 1;

    // Step 2: s0 -> s1 (Input 0)
    @(negedge clk);
    data_in = 0;

    // Step 3: s1 -> s1 (Verify hold stability with Input 0)
    @(negedge clk);
    data_in = 0;

    // Step 4: s1 -> s2 (Input 1)
    @(negedge clk);
    data_in = 1;

    // Step 5: s2 -> s3 (Input 0) -> CRITICAL: Output should go High
    @(negedge clk);
    data_in = 0;

    // Step 6: s3 -> s1 (Input 0)
    @(negedge clk);
    data_in = 0;

    // ------------------------------------------------------------
    // Sequence 2: False Path / Branch Coverage
    // Target: Verify s2 -> s0 transition (Broken Pulse)
    // ------------------------------------------------------------

    // Navigate back to s2: s1 -> s2
    @(negedge clk);
    data_in = 1;

    // s2 -> s0 (Input 1, Output should remain Low)
    @(negedge clk);
    data_in = 1;

    // ------------------------------------------------------------
    // Sequence 3: s3 State Transitions
    // Target: Verify s3 -> s2
    // ------------------------------------------------------------

    // Navigate to s3: s0 -> s1 -> s2 -> s3
    @(negedge clk); data_in = 0; // s0 -> s1
    @(negedge clk); data_in = 1; // s1 -> s2
    @(negedge clk); data_in = 0; // s2 -> s3

    // s3 -> s2 (Input 1)
    @(negedge clk);
    data_in = 1;

    // ------------------------------------------------------------
    // Sequence 4: Glitch / Combinational Logic Stress
    // Target: Toggle input within cycle at s2 to test Mealy output
    // ------------------------------------------------------------

    // Currently in s2 (from previous step s3->s2)
    @(negedge clk);
    // Toggle 0 (High Out) -> 1 (Low Out) -> 0 (High Out)
    // This ensures combinational logic reacts to input changes immediately
    data_in = 0; 
    #2;
    data_in = 1;
    #2;
    data_in = 0;

    // ------------------------------------------------------------
    // Sequence 5: Async Reset Check
    // Target: Assert reset during active operation
    // ------------------------------------------------------------
    @(negedge clk); // Capture s3
    #5;
    rst_n = 0;
    #10;
    rst_n = 1;
    data_in = 0;

    // 4. Cleanup
    #20;
    $display("LLM: Stimuli Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

